```json
{
    "subdivisionId": {subdivisionId},
    "createDate": {applyDate},
    "status": {
        "subdivisionStatusId": 2, // Совпадает с изначальным значением до редактирования
        "name": "Действующий" // Совпадает с изначальным значением до редактирования
    },
    "subdivisionNumber": null, // Совпадает с изначальным значением до редактирования
    "note": {Комментарий подразделения},
    "partner": false, //Совпадает с изначальным значением до редактирования
    "party": {
        "nameInfo": {
            "corporateName": {Наименование подразделения},
            "name": {Наименование подразделения}
        },
        "nationality": {
            "nationalityId": {Идентификатор страны регистрации}, 
            "name": "Россия" //Зависит от выбранной страны регистрации
        },
        "note": {Комментарий подразделения},
        "taxRegistrationCertificate": {
            "taxIdentificationNumber": {ИНН},
            "registrationReasonCode": {КПП},
            "PSRN": {ОГРН}
        }
    },
    "businessActivity": {
        "businessActivityId": {Идентификатор экономической деятельности},
        "name": "Страховая компания", // Зависит от выбранной экономической деятельности
        "code": "insuranceCompany" // Зависит от выбранной экономической деятельности
    }
}
```

* Все зафиксированные на шаге 1 данные совпадают с выведенными.

Пример ответа - [Результат редактирвоания подразделения прошлой датой](/api/rs/testcase/attachment/354230/content)"}
